use super::*;
use serde_json::{json,Value};
use std::panic::{catch_unwind,AssertUnwindSafe};
struct Listener{id:&'static str,group:Rc<KmoBookOpenEventListenerGroup>,log:Rc<RefCell<Vec<String>>>,other:RefCell<Option<Rc<dyn KmoBookOpenEventListener>>>,mutation:i32,thrown:Cell<bool>}
impl Listener{fn log(&self,s:&str){self.log.borrow_mut().push(format!("{}:{s}",self.id));}}
impl KmoBookOpenEventListener for Listener{
    fn onProgressChange(&self,p:i8){self.log(&format!("progress:{p}"));}
    fn bookDidFinishInitializing(&self,_b:&KmoBook){self.log("book");}
    fn activeSheetDidFinishInitializing(&self){self.log("active");if self.mutation==1{self.group.add(self.other.borrow().clone());}if self.mutation==2{self.group.clear();}if self.mutation==3&&!self.thrown.replace(true){panic!("FirstPageForceQuitException");}}
    fn sheetWillReadCurrentViewport(&self,s:i32){self.log(&format!("will:{s}"));}
    fn sheetDidFinishReadingCurrentViewport(&self,s:i32){self.log(&format!("viewport:{s}"));}
    fn sheetDidFinishReadingEverything(&self,s:i32){self.log(&format!("sheet:{s}"));}
    fn bookDidFinishReadingEverything(&self){self.log("end");}
}
fn call(f:impl FnOnce())->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(())=>json!({"result":"ok","value":null}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","ConcurrentModificationException","FirstPageForceQuitException","NoSuchElementException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
fn owner()->Value{use super::super::{KmoApp::KmoApp,KmoAppApi::KmoAppApi,BookOpenListener::BookOpenListener};let app=KmoApp::new();KmoAppApi::startup(&app);let books=app.books().unwrap();let sameBooks=Rc::ptr_eq(&books,&app.books().unwrap());let group=books.bookOpenListenerGroup.clone();books.addBookOpenEventListener(Some(Rc::new(BookOpenListener)));books.addBookOpenEventListener(Some(Rc::new(BookOpenListener)));let count=group.listeners.borrow().len();KmoAppApi::startup(&app);let current=app.books().unwrap();let size=current.bookOpenListenerGroup.listeners.borrow().len();json!({"sameBooks":sameBooks,"registered":count,"newBooksAfterStartup":!Rc::ptr_eq(&books,&current),"newGroupAfterStartup":!Rc::ptr_eq(&group,&current.bookOpenListenerGroup),"newGroupSize":size})}
#[test]
fn original_android_books_owner_and_open_listener_mutations(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/open-listener-r0b50");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let book=KmoBook::KmoBook();let mut all=vec![];for p in input["groups"].as_array().unwrap(){let group=Rc::new(KmoBookOpenEventListenerGroup::new());let log=Rc::new(RefCell::new(vec![]));let a=Rc::new(Listener{id:"a",group:group.clone(),log:log.clone(),other:RefCell::new(None),mutation:p["mutation"].as_i64().unwrap()as i32,thrown:Cell::new(false)});let b:Rc<dyn KmoBookOpenEventListener>=Rc::new(Listener{id:"b",group:group.clone(),log:log.clone(),other:RefCell::new(None),mutation:0,thrown:Cell::new(false)});*a.other.borrow_mut()=Some(b.clone());group.add(Some(a.clone()));if p["null"]==true{group.add(None);}group.add(Some(b));let mut rows=vec![];for c in p["commands"].as_array().unwrap(){let mut row=call(||match c.as_str().unwrap(){"progress"=>group.onProgressChange(-128),"book"=>group.bookDidFinishInitializing(&book),"active"=>group.activeSheetDidFinishInitializing(),"will"=>group.sheetWillReadCurrentViewport(i32::MIN),"viewport"=>group.sheetDidFinishReadingCurrentViewport(i32::MAX),"sheet"=>group.sheetDidFinishReadingEverything(-1),"end"=>group.bookDidFinishReadingEverything(),"addA"=>group.add(Some(a.clone())),"clear"=>group.clear(),s=>panic!("unexpected {s}")});row["log"]=json!(log.borrow().clone());rows.push(row);}group.clear();*a.other.borrow_mut()=None;all.push(rows);}let actual=json!({"groups":all,"owner":owner()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();assert_eq!(actual,java);}
